const token = (n = 32) => Array.from({ length: n }, () => 'abcdefghijkmnpqrstuvwxyz23456789'[Math.floor(Math.random() * 32)]).join('');

const clean = s => String(s ?? '').replace(/\s+\n/g, '\n').trim();
const join = (a, sep) => (Array.isArray(a) ? a : []).map(x => String(x).trim()).filter(Boolean).join(sep);
const scrub = s => String(s || '').replace(/[\w.+-]+@[\w-]+\.[\w.-]+/g, '[email removed]').replace(/(?:https?:\/\/)?(?:www\.)?linkedin\.com\/\S+/gi, '')
  .replace(/\+?\d[\d\s().-]{8,}\d/g, '[phone removed]');
function buildDoc(p, s, S, anon, ref) {
  const names = String(p.full_name || '').split(/\s+/).filter(n => n.length > 1);
  const deName = t => anon ? names.reduce((x, n) => x.replace(new RegExp('\\b' + n.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\b', 'gi'), 'the candidate'), scrub(t)) : t;
  const exp = (p.experience || []).map(e => {
    const who = anon && S.anonymise_companies === 'yes' ? (e.company_descriptor || 'Confidential employer') : e.company;
    return `${clean(e.title)}${who ? ', ' + clean(who) : ''}${e.location ? ' · ' + clean(e.location) : ''}\n${clean(e.start)} – ${clean(e.end) || 'Present'}` +
      ((e.highlights || []).length ? '\n' + e.highlights.map(h => '• ' + deName(clean(h))).join('\n') : '');
  }).join('\n\n');
  const edu = (p.education || []).map(e => [e.qualification, e.institution, e.year].filter(Boolean).map(clean).join(', ')).join('\n');
  const contactFull = [p.email, p.phone, p.linkedin].filter(Boolean).join(' · ');
  const rc = [S.recruiter_email, S.recruiter_phone].filter(x => x && !String(x).includes('YOUR_')).join(' · ');
  return {
    CANDIDATE_NAME: anon ? `Candidate ${ref}` : clean(p.full_name), HEADLINE: clean(p.headline), LOCATION: clean(p.location),
    CONTACT: anon ? `Represented by ${S.recruiter_name} (${S.agency_name}) · ${rc}` : contactFull, REFERENCE: ref,
    SUMMARY: deName(clean(p.summary)), KEY_SKILLS: join(p.key_skills, ' · '), EXPERIENCE: exp || 'See attached CV', EDUCATION: edu || '-',
    CERTIFICATIONS: join(p.certifications, '\n') || '-', LANGUAGES: join(p.languages, ', ') || '-',
    AVAILABILITY: clean(p.notice_period) || 'To be confirmed', SALARY: clean(p.salary_expectation) || 'On application',
    RIGHT_TO_WORK: clean(p.right_to_work) || 'To be confirmed', RECRUITER_NOTES: anon ? deName(s.recruiter_notes || '') : (s.recruiter_notes || ''),
    RECRUITER_NAME: S.recruiter_name, RECRUITER_CONTACT: rc, AGENCY_NAME: S.agency_name, DATE: $now.toFormat('d LLLL yyyy') };
}

// The text for every placeholder in your branded template
const S = $('Set formatter settings').first().json;
const src = $('Use the PDF text').all();
return $('Extract candidate profile').all().map((it, i) => {
  const p = it.json.output || {};
  const s = { ...src[i]?.json, recruiter_notes: String(src[i]?.json.recruiter_notes || '') };
  const initials = String(p.full_name || 'XX').split(/\s+/).map(n => n[0] || '').join('').toUpperCase().slice(0, 3);
  const ref = `${S.reference_prefix || 'CAND'}-${$now.toFormat('yyMMdd')}-${initials}${token(3).toUpperCase()}`;
  return { json: { reference: ref, doc_name: `${ref} - ${p.full_name || 'Candidate'}${s.role ? ' - ' + s.role : ''}`, r: buildDoc(p, s, S, false, ref), profile: p, source: s } };
});

// One row per document in the Candidates tab
const d = $('Plan documents').item.json;
const p = d.profile, s = d.source;
const doc = $('Copy branded template').item.json.id;
return { json: { logged_at: $now.toFormat('yyyy-MM-dd HH:mm'), reference: d.reference, version: d.version || 'full', candidate: p.full_name || '',
  email: p.email || '', phone: p.phone || '', headline: p.headline || '', location: p.location || '', years_experience: p.years_experience ?? '',
  seniority: p.seniority || '', sector: p.sector || '', key_skills: (p.key_skills || []).join(', '), notice_period: p.notice_period || '',
  salary_expectation: p.salary_expectation || '', right_to_work: p.right_to_work || '', client: s.client || '', role: s.role || '',
  source: s.source || 'form', original_file: s.file_name || '', doc_url: `https://docs.google.com/document/d/${doc}/edit`,
  pdf_url: $json.id ? `https://drive.google.com/file/d/${$json.id}/view` : '', duplicate_of: d.duplicate_of || '', recruiter_notes: s.recruiter_notes || '' } };

const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const rows = $('Prepare log row').all().map(i => i.json);
const li = rows.map(r => `<li><b>${esc(r.reference)}</b> ${esc(r.version === 'anonymised' ? 'anonymised profile' : r.candidate)}${r.role ? ' (' + esc(r.role) + ')' : ''}:
 <a href="${r.pdf_url}">PDF</a> · <a href="${r.doc_url}">edit in Google Docs</a>${r.duplicate_of ? ' · <b>already in your database</b>' : ''}</li>`).join('');
return [{ json: { subject: `Branded CV ready: ${[...new Set(rows.map(r => r.candidate))].join(', ')}`, html: `<ul>${li}</ul><p>Logged to the Candidates tab.</p>` } }];
